  test('parse PBES2 p12 with password', () {
    final pems = Pkcs12.parsePkcs12(b64(pbes2P12), password: '1234');
    expect(pems.length >= 2, true);
    expect(pems[0].contains('PRIVATE KEY'), true);
    expect(X509Utils.x509CertificateFromPem(pems[1]).subject['2.5.4.3'], 'test-client');
  });

  test('parse PBES2 p12 without password', () {
    final pems = Pkcs12.parsePkcs12(b64(pbes2NoPassP12));
    expect(pems[0].contains('PRIVATE KEY'), true);
  });

  test('parse legacy p12 with password', () {
    final pems = Pkcs12.parsePkcs12(b64(legacyP12), password: '1234');
    expect(pems[0].contains('PRIVATE KEY'), true);
    expect(X509Utils.x509CertificateFromPem(pems[1]).subject['2.5.4.3'], 'test-client');
  });

  test('wrong password throws', () {
    expect(() => Pkcs12.parsePkcs12(b64(pbes2P12), password: 'wrong'), throwsA(anything));
  });

  test('generatePkcs12 roundtrip', () {
    final p12 = Pkcs12.generatePkcs12(keyPem, [certPem], password: 'abc123');
    final pems = Pkcs12.parsePkcs12(p12, password: 'abc123');
    expect(pems[0].contains('PRIVATE KEY'), true);
    expect(X509Utils.x509CertificateFromPem(pems[1]).subject['2.5.4.3'], 'test-client');
  });
